using System.Windows.Forms;
using System.Drawing;
using W=System.Windows;
using C=System.Windows.Controls;
using M=System.Windows.Media;
using K=System.Windows.Input;
using S=System.Windows.Shapes;
namespace VelvetVoice;

internal static class WpfDialogs
{
    internal static MainForm? Model;
    internal static bool Active=>StudioWindow.Owner!=null;
    [System.Runtime.InteropServices.DllImport("dwmapi.dll")] static extern int DwmSetWindowAttribute(IntPtr window,int attribute,ref int value,int size);
    static W.Window Dialog(string title,double width,double height){var dialog=new W.Window{Title=title,Width=width,Height=height,Owner=StudioWindow.Owner,WindowStartupLocation=W.WindowStartupLocation.CenterOwner,Background=UiControls.Tone("#0D0B0A"),Foreground=UiControls.Ink,FontFamily=new M.FontFamily("Segoe UI"),FontSize=13,ResizeMode=W.ResizeMode.NoResize,Resources=StudioWindow.Owner!.Resources};dialog.SourceInitialized+=(_,_)=>{try{int enabled=1;DwmSetWindowAttribute(new System.Windows.Interop.WindowInteropHelper(dialog).Handle,20,ref enabled,4);}catch{}};return dialog;}
    static bool? Show(W.Window window){Model?.UiBoard.UiPauseKeys(true);try{return window.ShowDialog();}finally{Model?.UiBoard.UiPauseKeys(false);}}
    sealed class NativeOwner(IntPtr handle):IWin32Window {public IntPtr Handle=>handle;}
    internal static DialogResult OpenFile(OpenFileDialog dialog,Form legacyOwner){if(!Active)return dialog.ShowDialog(legacyOwner);Model?.UiBoard.UiPauseKeys(true);try{return dialog.ShowDialog(new NativeOwner(new System.Windows.Interop.WindowInteropHelper(StudioWindow.Owner!).Handle));}finally{Model?.UiBoard.UiPauseKeys(false);}}
    internal static string? Rename(string name)
    {
        var window=Dialog("Rename sound",460,230);var content=UiControls.Section("Give this pad a name");content.Margin=new W.Thickness(24);var input=new C.TextBox{Text=name,MaxLength=80,Margin=new W.Thickness(0,8,0,18)};content.Children.Add(input);var actions=new C.WrapPanel();var save=new C.Button{Content="Save name",IsDefault=true};save.Click+=(_,_)=>{if(!string.IsNullOrWhiteSpace(input.Text))window.DialogResult=true;};var cancel=new C.Button{Content="Cancel",IsCancel=true};actions.Children.Add(save);actions.Children.Add(cancel);content.Children.Add(actions);window.Content=content;window.Loaded+=(_,_)=>{input.Focus();input.SelectAll();};return Show(window)==true?input.Text.Trim():null;
    }
    internal static KeyBinding? Shortcut(KeyBinding? existing,bool allowClear)
    {
        KeyDialog.Accepted=false;KeyBinding? result=existing;var window=Dialog("Assign shortcut",500,270);var content=UiControls.Section("Choose your shortcut","Assigned keys also reach your game. Holding a key does not repeat.");content.Margin=new W.Thickness(24);var input=new C.TextBox{Text=existing?.ToString()??"Click here and press keys…",IsReadOnly=true,Margin=new W.Thickness(0,8,0,18)};content.Children.Add(input);
        input.PreviewKeyDown+=(_,e)=>{e.Handled=true;var key=e.Key==K.Key.System?e.SystemKey:e.Key;if(key is K.Key.LeftCtrl or K.Key.RightCtrl or K.Key.LeftAlt or K.Key.RightAlt or K.Key.LeftShift or K.Key.RightShift or K.Key.LWin or K.Key.RWin)return;int modifiers=(K.Keyboard.Modifiers.HasFlag(K.ModifierKeys.Alt)?1:0)|(K.Keyboard.Modifiers.HasFlag(K.ModifierKeys.Control)?2:0)|(K.Keyboard.Modifiers.HasFlag(K.ModifierKeys.Shift)?4:0);result=new KeyBinding(K.KeyInterop.VirtualKeyFromKey(key),modifiers);input.Text=result.ToString();};
        var actions=new C.WrapPanel();var save=new C.Button{Content="Save shortcut"};save.Click+=(_,_)=>{if(result!=null){KeyDialog.Accepted=true;window.DialogResult=true;}};actions.Children.Add(save);if(allowClear){var clear=new C.Button{Content="Clear binding"};clear.Click+=(_,_)=>{result=null;KeyDialog.Accepted=true;window.DialogResult=true;};actions.Children.Add(clear);}actions.Children.Add(new C.Button{Content="Cancel",IsCancel=true});content.Children.Add(actions);window.Content=content;window.Loaded+=(_,_)=>input.Focus();Show(window);return KeyDialog.Accepted?result:null;
    }
    internal static (double Start,double End)? Trim(AudioClip clip,SoundEntry entry,Action<AudioClip> preview)
    {
        var window=Dialog("Trim pad · "+entry.Name,800,500);var content=UiControls.Section("Keep the best part","Full audio stays on disk. Reset restores the original range.");content.Margin=new W.Thickness(24);var canvas=new C.Canvas{Height=145,Background=UiControls.Panel,ClipToBounds=true,Margin=new W.Thickness(0,8,0,18)};content.Children.Add(canvas);var fields=new C.WrapPanel();var bounds=ClipTrim.Bounds(clip,entry.TrimStart,entry.TrimEnd);var start=new C.TextBox{Text=(bounds.Start/(double)clip.SampleRate).ToString("0.000"),Width=100,Margin=new W.Thickness(10,0,24,12)};var end=new C.TextBox{Text=(bounds.End/(double)clip.SampleRate).ToString("0.000"),Width=100,Margin=new W.Thickness(10,0,0,12)};fields.Children.Add(UiControls.Text("Start · seconds",12,UiControls.Muted));fields.Children.Add(start);fields.Children.Add(UiControls.Text("End · seconds",12,UiControls.Muted));fields.Children.Add(end);content.Children.Add(fields);var detail=UiControls.Text("",12,UiControls.Muted);content.Children.Add(detail);
        bool Range(out double a,out double b){bool valid=double.TryParse(start.Text,out a)&&double.TryParse(end.Text,out b);b=double.TryParse(end.Text,out var second)?second:0;return valid&&double.IsFinite(a)&&double.IsFinite(b)&&a>=0&&b<=clip.Seconds+.0005&&b-a>=1.0/clip.SampleRate;}
        void Draw(){canvas.Children.Clear();double width=canvas.ActualWidth;if(width<=0||clip.Samples.Length==0)return;bool valid=Range(out var a,out var b);if(valid){var shade=new S.Rectangle{Width=Math.Max(0,(b-a)/clip.Seconds*width),Height=145,Fill=UiControls.Tone("#46301F")};C.Canvas.SetLeft(shade,a/clip.Seconds*width);canvas.Children.Add(shade);}for(int x=0;x<(int)width;x++){int first=x*clip.Samples.Length/(int)width,last=Math.Max(first+1,(x+1)*clip.Samples.Length/(int)width);float peak=0;for(int i=first;i<Math.Min(last,clip.Samples.Length);i++)peak=Math.Max(peak,Math.Abs(clip.Samples[i]));canvas.Children.Add(new S.Line{X1=x,X2=x,Y1=72-Math.Max(1,peak*65),Y2=72+Math.Max(1,peak*65),Stroke=UiControls.Accent,StrokeThickness=1});}detail.Text=valid?$"Selection {(b-a):0.000}s · original {clip.Seconds:0.000}s":"Enter a valid range with end after start.";}
        start.TextChanged+=(_,_)=>Draw();end.TextChanged+=(_,_)=>Draw();canvas.SizeChanged+=(_,_)=>Draw();var actions=new C.WrapPanel();var reset=new C.Button{Content="Reset"};reset.Click+=(_,_)=>{start.Text="0.000";end.Text=clip.Seconds.ToString("0.000");};var listen=new C.Button{Content="Preview selection"};listen.Click+=(_,_)=>{if(Range(out var a,out var b))preview(ClipTrim.Apply(clip,a,b));};var save=new C.Button{Content="Save trim",IsDefault=true};save.Click+=(_,_)=>{if(Range(out _,out _))window.DialogResult=true;};actions.Children.Add(reset);actions.Children.Add(listen);actions.Children.Add(save);actions.Children.Add(new C.Button{Content="Cancel",IsCancel=true});content.Children.Add(actions);window.Content=content;return Show(window)==true&&Range(out var firstValue,out var lastValue)?(firstValue,lastValue):null;
    }
    internal static string[] Verify()
    {
        var log=new List<string>();
        void Schedule(string expected,Action<W.Window> action){StudioWindow.Owner!.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Background,(Action)(()=>{var dialog=W.Application.Current.Windows.Cast<W.Window>().Single(x=>x!=StudioWindow.Owner&&x.Title.StartsWith(expected,StringComparison.Ordinal));if(Model?.Enabled!=false)throw new Exception("Global keys not paused during modal");dialog.UpdateLayout();action(dialog);}));}
        void SaveImage(W.Window dialog,string name){dialog.UpdateLayout();var image=new System.Windows.Media.Imaging.RenderTargetBitmap((int)dialog.ActualWidth,(int)dialog.ActualHeight,96,96,M.PixelFormats.Pbgra32);image.Render(dialog);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(image));using var file=File.Create(Path.Combine(AppContext.BaseDirectory,"preview-dialog-"+name+".png"));encoder.Save(file);}
        void Click(W.Window dialog,string caption){Find<C.Button>(dialog).Single(x=>x.Content?.ToString()==caption).RaiseEvent(new W.RoutedEventArgs(C.Button.ClickEvent));}
        Schedule("Rename sound",dialog=>{Find<C.TextBox>(dialog).Single().Text="Renamed fixture";SaveImage(dialog,"rename");Click(dialog,"Save name");});if(Rename("Fixture")!="Renamed fixture")throw new Exception("WPF rename validation");log.Add("PASS native rename dialog and modal shortcut pause");
        var existing=new KeyBinding((int)Keys.F6,3);Schedule("Assign shortcut",dialog=>{SaveImage(dialog,"shortcut");Click(dialog,"Save shortcut");});if(Shortcut(existing,true)!=existing||!KeyDialog.Accepted)throw new Exception("WPF shortcut save");log.Add("PASS native shortcut dialog preserves assigned binding");
        var samples=new AudioClip(Enumerable.Range(0,48000).Select(i=>(float)(.2*Math.Sin(i*.05))).ToArray(),48000);AudioClip? preview=null;Schedule("Trim pad",dialog=>{var inputs=Find<C.TextBox>(dialog).ToArray();inputs[0].Text="0.250";inputs[1].Text="0.750";SaveImage(dialog,"trim");Click(dialog,"Preview selection");Click(dialog,"Save trim");});var bounds=Trim(samples,new SoundEntry("fixture","Fixture pad","unused"),clip=>preview=clip);if(bounds is not {} range||range.Start!=.25||range.End!=.75||preview?.Samples.Length!=24000)throw new Exception("WPF trim or private preview selection");if(Model?.Enabled!=true)throw new Exception("Modal shortcut pause did not release");log.Add("PASS native trim range and synthetic preview callback; shortcuts resume after close");return log.ToArray();
    }
    static IEnumerable<T> Find<T>(W.DependencyObject root) where T:W.DependencyObject{for(int i=0;i<M.VisualTreeHelper.GetChildrenCount(root);i++){var child=M.VisualTreeHelper.GetChild(root,i);if(child is T match)yield return match;foreach(var nested in Find<T>(child))yield return nested;}}
}

